WITH SupplierSummary AS (SELECT supplier_id, ROUND((100 * SUM(CASE WHEN category = 'Sports' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_sports, MAX(stock_qty) - MIN(stock_qty) AS stock_qty_range FROM products WHERE category != 'Electronics' GROUP BY supplier_id) SELECT suppliers.id, suppliers.city, suppliers.country, SupplierSummary.pct_sports, SupplierSummary.stock_qty_range FROM suppliers INNER JOIN SupplierSummary ON suppliers.id = SupplierSummary.supplier_id ORDER BY stock_qty_range DESC;
